function orbitAuth(){document.body.classList.add('signed-out');content.innerHTML=`<div class="auth-wrap"><div class="auth-card card"><a class="brand auth-brand"><span class="brand-mark">◈</span><span>Code Insight AI</span></a><div class="eyebrow">YOUR CODEBASE, UNDERSTOOD</div><h1>${orbitSignup?'Create your account':'Welcome back'}</h1><p class="subtitle">${orbitSignup?'Create a private workspace for your project intelligence.':'Sign in to your private project intelligence workspace.'}</p><form id="orbitAuthForm"><label class="form-label">EMAIL</label><input class="form-input" name="email" type="email" required autocomplete="email" placeholder="you@company.com"><label class="form-label">PASSWORD</label><input class="form-input" name="password" type="password" required minlength="12" autocomplete="${orbitSignup?'new-password':'current-password'}" placeholder="${orbitSignup?'At least 12 characters':'Your password'}">${orbitSignup?'<div class="skeleton-note" style="margin-top:7px">Use at least 12 characters. Your account and projects are stored in your PostgreSQL database.</div>':''}<button class="btn primary" style="width:100%;justify-content:center;margin-top:19px">${orbitSignup?'Create account':'Sign in'} →</button></form><p class="auth-switch">${orbitSignup?'Already have an account?':'New to Code Insight AI?'} <button id="orbitSwitchAuth">${orbitSignup?'Sign in':'Create an account'}</button></p><div class="auth-foot">SELF-HOSTED · YOUR DATABASE · YOUR REPOSITORIES</div></div></div>`;$('#orbitAuthForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await orbitApi(`/auth/${orbitSignup?'signup':'login'}`,{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});orbitUser=r.user;document.body.classList.remove('signed-out');await orbitLoadProjects()}catch(err){toast(err.message)}};$('#orbitSwitchAuth').onclick=()=>{orbitSignup=!orbitSignup;orbitAuth()}}
function orbitEmpty(){return `${pageHeader('YOUR PRIVATE WORKSPACE','Connect your first repository','Create a project from a GitHub repository. Orbit will index its source tree, build a baseline architecture map, generate clear repository-grounded documentation, and track future pushes.',`<button class="btn primary" data-live-action="repo">＋ &nbsp; Connect GitHub repository</button>`)}<div class="bottom-grid"><div class="card mini-card"><div class="mini-icon">◉</div><h3>Private by default</h3><p>Repository access tokens are encrypted in PostgreSQL. Project API data is scoped to your account.</p></div><div class="card mini-card"><div class="mini-icon">⌑</div><h3>Real repository baseline</h3><p>Source files and module relationships are indexed before the first impact analysis is shown.</p></div><div class="card mini-card"><div class="mini-icon">✳</div><h3>Source-grounded answers</h3><p>Ask questions against indexed code. Add an AI key on the server for synthesized answers with source citations.</p></div></div>`}
const orbitEmptyBase=orbitEmpty;orbitEmpty=function(){const title=$('#projectSelect .project-select-copy b'),sub=$('#projectSelect .project-select-copy small'),icon=$('#projectSelect .project-icon');if(title)title.textContent='No projects';if(sub)sub.textContent='Connect a GitHub repository';if(icon)icon.textContent='+';return orbitEmptyBase()};
async function orbitLoadProjects(preferred){try{const r=await orbitApi('/projects');state.projects=r.projects.map(p=>({id:p.id,name:p.name,repo:`${p.repo_owner}/${p.repo_name}`,initial:p.name[0]?.toUpperCase()||'P',color:'#6e79ed',...p}));if(!state.projects.length){orbitProject=null;render();return}orbitProject=state.projects.find(p=>p.id===(preferred||orbitProject?.id))||state.projects[0];await orbitLoadProject() }catch(e){if(e.message.includes('Sign in')){orbitUser=null;orbitAuth()}else toast(e.message)}}
