 const order=['Root files','API routes','Data models','Web client','Request middleware','Shared utilities','Project scripts','Contract migrations','Generated contract artifacts','Generated build cache','Project specifications','Developer settings'];const groupNames=[...groups.keys()].sort((a,b)=>(order.indexOf(a)<0?999:order.indexOf(a))-(order.indexOf(b)<0?999:order.indexOf(b))||a.localeCompare(b));
 const groupedEdges=new Map();for(const e of g.edges||[]){const from=bucketByFile.get(e.from),to=bucketByFile.get(e.to);if(!from||!to||from===to)continue;const key=`${from}\u0000${to}`;groupedEdges.set(key,(groupedEdges.get(key)||0)+1)}
 const nodeStyle=[{selector:'node',style:{'shape':'round-rectangle','background-color':color('--panel2','#18212d'),'border-width':2,'border-color':color('--border2','#455266'),'label':'data(label)','color':color('--text','#f2f4f7'),'font-family':'DM Sans, Arial, sans-serif','font-size':15,'font-weight':600,'text-wrap':'wrap','text-max-width':195,'text-valign':'center','text-halign':'center','width':240,'height':120,'padding':'10px'}},{selector:'node[kind = "flow"]',style:{'border-color':color('--green','#a4e66a'),'background-color':color('--greenwash','#1b2a20')}},{selector:'node[kind = "entry"]',style:{'border-color':color('--green','#a4e66a'),'background-color':color('--panel2','#18212d')}},{selector:'node[kind = "file"]',style:{'border-color':color('--blue','#6e88e8')}},{selector:'node[kind = "module"]',style:{'border-color':color('--green','#75ad55'),'background-color':color('--greenwash','#1b2a20'),'width':230,'height':112,'font-size':14,'text-max-width':185}},{selector:'node:selected',style:{'border-width':4,'border-color':color('--cyan','#65c9cc')}},{selector:'edge',style:{'width':3,'line-color':color('--blue','#7790ee'),'target-arrow-color':color('--blue','#7790ee'),'target-arrow-shape':'triangle','curve-style':'bezier','label':'data(label)','font-size':11,'font-family':'DM Mono, monospace','color':color('--muted','#a4afbd'),'text-background-color':color('--panel','#11161e'),'text-background-opacity':1,'text-background-padding':3,'text-rotation':'none','arrow-scale':1.15}}];
 if(useFlow){steps.forEach((step,i)=>els.push({data:{id:step.id,label:`STEP ${String(i+1).padStart(2,'0')}\n${step.label}\n${step.detail||''}${step.file?`\n${step.file}`:''}`,file:step.file||'',kind:'flow'}}));flowEdges.forEach((e,i)=>els.push({data:{id:`flow-${i}`,source:e.from,target:e.to,label:e.type||''}}))}
 else if(mode==='files'){const visible=sourceNodes.slice(0,80),ids=new Set(visible.map(n=>n.id));visible.forEach(n=>els.push({data:{id:n.id,label:`${n.label}\n${n.id}`,file:n.id,kind:'file'}}));(g.edges||[]).filter(e=>ids.has(e.from)&&ids.has(e.to)).slice(0,160).forEach((e,i)=>els.push({data:{id:`import-${i}`,source:e.from,target:e.to,label:'imports'}}))}
