 orbitCy.on('tap','node',async event=>{const d=event.target.data();if(d.kind==='module'){const files=groups.get(d.moduleName)||[];showModal(`${orbitEsc(d.moduleName)} · ${files.length} files`,`<p class="subtitle">Select a repository file to inspect its indexed source.</p><div class="file-list">${files.map(n=>`<button class="file-row" data-graph-file="${orbitEsc(n.id)}" style="width:100%;text-align:left"><span class="file-symbol">▤</span>${orbitEsc(n.id)}</button>`).join('')}</div>`,`<button class="btn" data-close>Close</button>`);document.querySelector('#modalRoot [data-close]').onclick=closeModal;document.querySelectorAll('[data-graph-file]').forEach(el=>el.onclick=()=>openGraphFile(el.dataset.graphFile));return}if(d.file)openGraphFile(d.file)});
