async function orbitRenderChanges(){let c=commits[state.activeCommit||0];if(!c)return `${pageHeader('CHANGE INTELLIGENCE','Change intelligence','Push a commit to GitHub to see file diffs, affected modules, and risk analysis.')}`;const impact=c.impact||{};return `${pageHeader('CHANGE INTELLIGENCE','Every change, understood.','Commit history and impact analysis generated from your connected repository.',`<button class="btn" data-live-action="sync">⚡ &nbsp; Sync now</button>`)}<div class="row" style="margin-bottom:13px"><div class="card" style="padding:9px 13px;flex:1">${activity(8)}</div><span class="tag green">● &nbsp; GITHUB TRACKING</span></div><div class="card" style="margin-bottom:14px">${cardTitle('Impact analysis',`${c.hash} · ${orbitEsc(c.title)}`,`<span class="tag ${impact.risk==='high'?'red':impact.risk==='medium'?'yellow':'green'}">${orbitEsc(impact.risk||'baseline')} risk</span>`)}<p class="subtitle">${orbitEsc(impact.summary||'Initial repository architecture and dependency baseline.')}</p><div class="impact-summary"><div class="impact-pill"><small>FILES CHANGED</small><b>${impact.changed_files??c.files}</b></div><div class="impact-pill"><small>DIRECT MODULES</small><b>${impact.direct_modules?.length||0}</b></div><div class="impact-pill"><small>INDIRECT FILES</small><b>${impact.indirect_files?.length||0}</b></div></div>${(impact.files||[]).length?`<div class="file-list">${impact.files.map(f=>`<div class="file-row"><span class="file-symbol ${f.status==='added'?'file-add':'file-change'}">${f.status==='added'?'A':f.status==='removed'?'D':'M'}</span>${orbitEsc(f.path)}</div>`).join('')}</div>`:'<div class="callout">Initial baseline: this architecture graph establishes the dependency reference point for future commit impact analysis.</div>'}<div class="risk-box"><b>${impact.risk==='high'?'High':impact.risk==='medium'?'Moderate':'Baseline'} impact</b><br>${orbitEsc(impact.summary||'The initial baseline captures the project modules and internal imports.')}</div></div><div class="change-grid"><section class="card">${cardTitle('Before & after',orbitDiff?.files?.[0]?.path||'Select a commit to inspect its file diff')}${orbitDiff?.baseline?'<p class="skeleton-note">This is the initial commit. No previous project snapshot exists.</p>':orbitDiff?.files?.length?orbitDiff.files.slice(0,5).map(f=>`<div class="diff-head">${orbitEsc(f.status)} · ${orbitEsc(f.path)}</div><div class="diff-code">${f.before.split('\n').slice(0,12).map(x=>`<div class="removed">− ${orbitEsc(x)}</div>`).join('')}${f.after.split('\n').slice(0,12).map(x=>`<div class="added">+ ${orbitEsc(x)}</div>`).join('')}</div>`).join(''):'<p class="skeleton-note">Loading repository diff…</p>'}</section><section class="card">${cardTitle('Dependency graph','Changed files connected to indexed modules')}${orbitImpactGraph(impact)}<div class="file-list">${(impact.direct_modules||[]).map(m=>`<div class="file-row"><span class="file-symbol">⬡</span>${orbitEsc(m)}</div>`).join('')||'<p class="skeleton-note">No changed module relationships in this snapshot.</p>'}</div></section></div>`}
