function orbitImpactGraph(i){const edges=i.graph_edges||[];const changed=new Set((i.files||[]).map(f=>f.path));const ids=[...new Set([...changed,...(i.indirect_files||[]),...edges.flatMap(e=>[e.from,e.to])])].slice(0,9);if(!ids.length)return '<div class="impact-map"><span class="skeleton-note">Initial baseline graph is available on the Architecture page.</span></div>';const pos=new Map(ids.map((id,n)=>[id,{x:12+(n%3)*215,y:14+Math.floor(n/3)*52}]));return `<div class="impact-svg"><svg viewBox="0 0 660 ${Math.ceil(ids.length/3)*52+15}">${edges.filter(e=>pos.has(e.from)&&pos.has(e.to)).map(e=>{const a=pos.get(e.from),b=pos.get(e.to);return `<path class="arch-edge" d="M${a.x+195} ${a.y+18} C${a.x+205} ${a.y+18} ${b.x-5} ${b.y+18} ${b.x} ${b.y+18}"/>`}).join('')}${ids.map(id=>{const p=pos.get(id);return `<g><rect x="${p.x}" y="${p.y}" width="190" height="36" rx="6" class="impact-svg-node ${changed.has(id)?'is-changed':''}"/><text x="${p.x+8}" y="${p.y+22}">${orbitEsc(id).slice(-27)}</text></g>`}).join('')}</svg></div>`}
function orbitOverview(){const total=orbitStats?.files||orbitFiles.length,mods=orbitKnowledge?.graph?.modules||[],commitCount=orbitStats?.commits||commits.length,open=commits.filter(c=>c.impact?.risk==='high').length;return `${pageHeader('CONNECTED REPOSITORY',orbitProject.name,`${orbitProject.repo_owner}/${orbitProject.repo_name} · branch ${orbitProject.default_branch} · last indexed ${orbitTime(orbitProject.last_indexed_at)}`,`<button class="btn" data-live-action="repo">↗ &nbsp; Repository settings</button>`)}<div class="stats"><div class="stat-card"><div class="stat-top"><span>INDEXED SOURCE FILES</span><span class="stat-icon">▤</span></div><div class="stat-num">${total}</div><div class="stat-foot">${orbitProject.last_commit_sha?'Current commit snapshot':'Indexing in progress'}</div></div><div class="stat-card"><div class="stat-top"><span>MODULE GROUPS</span><span class="stat-icon">⬡</span></div><div class="stat-num">${mods.length}</div><div class="stat-foot">Derived from repository paths</div></div><div class="stat-card"><div class="stat-top"><span>COMMITS INDEXED</span><span class="stat-icon">⌘</span></div><div class="stat-num">${commitCount}</div><div class="stat-foot">Since project connection</div></div><div class="stat-card"><div class="stat-top"><span>HIGH IMPACT CHANGES</span><span class="stat-icon">◎</span></div><div class="stat-num">${open}</div><div class="stat-foot">From indexed commit history</div></div></div><div class="overview-grid"><section class="card">${cardTitle('Repository structure','Files and internal module relationships from the current index',`<button class="btn small" data-nav="architecture">Explore graph ↗</button>`)}<div class="module-list">${mods.slice(0,9).map(m=>`<div class="module-row"><i class="module-color"></i><span>${orbitEsc(m.name)}</span><small>${m.count} files</small></div>`).join('')||'<p class="skeleton-note">The first source index is being built. This page updates when it completes.</p>'}</div><div class="progress"><i style="width:${Math.min(100,Math.max(4,mods.length*12))}%"></i></div><p class="skeleton-note">${orbitKnowledge?.graph?.edges?.length||0} resolved internal import relationships</p></section><section class="card">${cardTitle('Recent commits','Changes detected from the connected GitHub repository',`<button class="btn small" data-nav="changes">View impact ↗</button>`)}${commits.length?activity(5):'<p class="skeleton-note">Waiting for the first repository index.</p>'}</section></div><div class="bottom-grid"><div class="card mini-card"><div class="mini-icon">▤</div><h3>Project documentation</h3><p>${docs.length} source-grounded guides explain setup, structure, architecture, important files, interfaces, data, and operations.</p><span class="mini-link" data-nav="documentation">Explore the guides →</span></div><div class="card mini-card"><div class="mini-icon">✳</div><h3>Ask this project</h3><p>Questions are retrieved against indexed code${orbitStatus?.assistant?' and synthesized with your configured AI model':'. Add an OpenAI key on the server for synthesized responses'}.</p><button class="btn small" data-nav="assistant">Start a conversation ↗</button></div></div>`}
let orbitStatus=null;
function orbitMarkdownExport(){return docs.map(d=>`# ${d[0]}\n\n${d[1]}`).join('\n\n---\n\n')}
function orbitHtmlPage(heading,body){return `<!doctype html><meta charset="utf-8"><title>${orbitEsc(heading)}</title><style>body{font:13pt Arial;max-width:760px;margin:35px auto;color:#202b28;line-height:1.6}section{page-break-after:always;min-height:900px;padding:25px}h1{font-size:24pt}h2{border-bottom:1px solid #aaa;padding-bottom:10px}.meta{color:#64736e;font-size:10pt}</style><h1>${orbitEsc(heading)}</h1>${body}`}
function orbitRenderVersions(){return `${pageHeader('PROJECT HISTORY','Version history',`${orbitVersions.length} preserved documentation and source snapshots.`,``)}<section class="card">${cardTitle('Repository snapshots','Each indexed revision points to its source inventory and generated knowledge.')}${commits.map((c,i)=>`<div class="version-row"><span class="hash">${c.hash}</span><div><b style="font-size:11px">${orbitEsc(c.title)}</b><div class="timeline-meta">${orbitEsc(c.author)} · ${c.time} · ${c.files} files</div></div><button class="btn small" data-commit="${i}">View impact</button></div>`).join('')||'<p class="skeleton-note">No commit snapshots yet.</p>'}</section><section class="card" style="margin-top:14px">${cardTitle('Knowledge snapshots','Generated documentation remains linked to immutable commit hashes.')}<div class="file-list">${orbitVersions.map(v=>`<div class="file-row"><span class="file-symbol">◷</span>${orbitEsc(v.commit_sha.slice(0,12))}<span>${new Date(v.generated_at).toLocaleString()}</span><span>${orbitEsc(v.message||'Documentation snapshot')}</span></div>`).join('')}</div></section>`}
function orbitSettings(){return `${pageHeader('PROJECT CONFIGURATION','Project settings','Repository connection and indexing status.',`<button class="btn" data-live-action="sync">⚡ &nbsp; Sync now</button>`)}<div class="settings-grid"><section class="card settings-card">${cardTitle('GitHub connection')}<div class="settings-row"><div><b>Repository</b><small>${orbitEsc(orbitProject.repo_owner)}/${orbitEsc(orbitProject.repo_name)}</small></div><span class="tag green">Connected</span></div><div class="settings-row"><div><b>Default branch</b><small>Indexed push updates</small></div><span class="tag">${orbitEsc(orbitProject.default_branch)}</span></div><div class="settings-row"><div><b>Latest snapshot</b><small>${orbitProject.last_indexed_at?new Date(orbitProject.last_indexed_at).toLocaleString():'Indexing'}</small></div><span class="tag">${orbitProject.last_commit_sha?.slice(0,7)||'Pending'}</span></div><p class="skeleton-note">A signed GitHub push webhook was installed when repository permissions allowed it. Otherwise configure the endpoint shown when connecting.</p></section><section class="card settings-card">${cardTitle('Index status')}<div class="settings-row"><div><b>Indexed files</b><small>Generated/dependency directories excluded</small></div><span class="tag">${orbitFiles.length}</span></div><div class="settings-row"><div><b>Knowledge snapshot</b><small>Project guides + dependency graph</small></div><span class="tag">${orbitKnowledge?'Ready':'Indexing'}</span></div><div class="settings-row"><div><b>Optional graph storage</b><small>Neo4j is optional; Graph data also lives in PostgreSQL.</small></div><span class="tag">${orbitStatus?.graph?'Connected':'PostgreSQL'}</span></div><div class="settings-row"><div><b>AI assistant</b><small>${orbitStatus?.assistant?'Model API configured':'Code excerpt retrieval active; configure OpenAI key for synthesis'}</small></div><span class="tag">${orbitStatus?.assistant?'AI':'Source retrieval'}</span></div></section><section class="card settings-card"><button class="btn" data-live-action="deleteProject">Remove this project</button><p class="skeleton-note" style="margin-top:8px">Removes this project's records and encrypted token from PostgreSQL.</p></section></div>`}
function orbitBind(){content.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(el.dataset.nav));content.querySelectorAll('[data-live-action]').forEach(el=>el.onclick=()=>orbitAction(el.dataset.liveAction));content.querySelectorAll('[data-doc]').forEach(el=>el.onclick=()=>{state.docIndex=+el.dataset.doc;render()});content.querySelectorAll('[data-doc-prev],[data-doc-next]').forEach(el=>el.onclick=()=>{state.docIndex=Number(el.dataset.docNext??el.dataset.docPrev);render()});content.querySelectorAll('[data-node]').forEach(el=>el.onclick=async()=>{const n=orbitKnowledge?.graph?.nodes?.[+el.dataset.node];if(!n)return;try{const f=await orbitApi(`/projects/${orbitProject.id}/file?path=${encodeURIComponent(n.id)}`);const incoming=orbitKnowledge.graph.edges.filter(e=>e.to===n.id).map(e=>e.from),outgoing=orbitKnowledge.graph.edges.filter(e=>e.from===n.id).map(e=>e.to);showModal(n.id,`<div class="doc-meta">${orbitEsc(f.language)} · ${incoming.length} incoming links · ${outgoing.length} outgoing links</div><p class="skeleton-note">Imports: ${orbitEsc((f.imports||[]).join(', ')||'none detected')}</p><pre class="source-preview">${orbitEsc(f.content.slice(0,12000))}${f.content.length>12000?'\n… truncated':''}</pre>`,`<button class="btn" data-close>Close</button>`);$('#modalRoot [data-close]').onclick=closeModal}catch(e){toast(e.message)}});content.querySelectorAll('[data-commit]').forEach(el=>el.onclick=async()=>{state.activeCommit=+el.dataset.commit;orbitDiff=null;orbitDiffLoading=false;state.page='changes';render()});content.querySelectorAll('[data-graph-mode]').forEach(el=>el.onclick=()=>{state.architectureMode=el.dataset.graphMode;render()});content.querySelectorAll('[data-graph-action]').forEach(el=>el.onclick=()=>{if(!orbitCy)return;if(el.dataset.graphAction==='fit')orbitCy.fit(undefined,45);if(el.dataset.graphAction==='zoomIn')orbitCy.zoom({level:orbitCy.zoom()*1.2,renderedPosition:{x:orbitCy.width()/2,y:orbitCy.height()/2}});if(el.dataset.graphAction==='zoomOut')orbitCy.zoom({level:orbitCy.zoom()/1.2,renderedPosition:{x:orbitCy.width()/2,y:orbitCy.height()/2}})});if($('#chatForm'))$('#chatForm').onsubmit=e=>{e.preventDefault();orbitAsk($('#chatInput').value)};content.querySelectorAll('[data-prompt]').forEach(el=>el.onclick=()=>orbitAsk(el.dataset.prompt));if(state.page==='architecture')orbitMountArchitectureGraph()}
render=function(){document.body.classList.toggle('theme-light',state.theme==='light');if(!orbitUser){orbitAuth();return}document.body.classList.remove('signed-out');let n={overview:'Overview',documentation:'Documentation',architecture:'Architecture',changes:'Change intelligence',assistant:'Project assistant',versions:'Versions',settings:'Settings'};$('#crumbCurrent').textContent=n[state.page]||'Overview';$('#projectBreadcrumb').textContent=orbitProject?.name||'Workspace';$$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.page===state.page));if(orbitProject){$('#projectSelect .project-select-copy b').textContent=orbitProject.name;$('#projectSelect .project-select-copy small').textContent=`${orbitProject.repo_owner} / ${orbitProject.repo_name}`;$('#projectSelect .project-icon').textContent=orbitProject.name[0]?.toUpperCase()||'P';$('.profile .profile-copy b')?.replaceChildren(document.createTextNode(orbitUser.email||'Account'))}if(!orbitProject){content.innerHTML=orbitEmpty();orbitBind();return}if(orbitLoading){content.innerHTML=`${pageHeader('CONNECTING REPOSITORY','Building your project baseline','Reading the repository tree, source files, and dependencies. The first architecture graph and impact baseline appear as soon as indexing finishes.') }<div class="card mini-card"><span class="sync-pulse"></span> Indexing ${orbitEsc(orbitProject.repo_owner)}/${orbitEsc(orbitProject.repo_name)}…</div>`;return}if(!orbitKnowledge&&!orbitProject.last_commit_sha){const failed=orbitProject.index_status==='error';content.innerHTML=`${pageHeader(failed?'INDEX ERROR':'INITIAL INDEX',failed?'Could not read the repository':'Reading the repository',failed?orbitProject.index_error:'Orbit is building the initial source snapshot. This page updates as soon as it completes.') }<div class="card mini-card">${failed?`<button class="btn" data-live-action="sync">Retry indexing</button>`:'<span class="sync-pulse"></span> Scanning GitHub source tree…'}</div>`;orbitBind();if(!failed)setTimeout(()=>orbitLoadProject(),5000);return}const views={overview:orbitOverview,documentation:orbitRenderDocs,architecture:orbitArchitecture,changes:()=>{orbitRenderChanges().then(html=>{if(state.page==='changes'){content.innerHTML=html;orbitBind()}});return `${pageHeader('CHANGE INTELLIGENCE','Loading commit impact','Fetching before and after source snapshots.')}`},versions:orbitRenderVersions,settings:orbitSettings,assistant:assistant};content.innerHTML=(views[state.page]||orbitOverview)();orbitBind();if(state.page==='changes'&&!orbitDiff&&!orbitDiffLoading&&commits[state.activeCommit||0]){orbitDiffLoading=true;orbitApi(`/projects/${orbitProject.id}/commits/${commits[state.activeCommit||0].sha}/diff`).then(d=>{orbitDiff=d;orbitDiffLoading=false;render()}).catch(e=>{orbitDiffLoading=false;toast(e.message)})}};
function orbitShowRepo(){showModal('Connect a GitHub repository',`<p class="subtitle">Orbit will fetch the repository tree, index source files, create an initial architecture/dependency baseline, generate source-grounded guides, then track pushes with a signed webhook.</p><label class="form-label">PROJECT NAME</label><input class="form-input" id="modalProject" placeholder="e.g. Atlas API"><label class="form-label">GITHUB REPOSITORY URL</label><input class="form-input" id="modalRepo" placeholder="https://github.com/owner/repository"><label class="form-label">GITHUB TOKEN <span class="muted">· OPTIONAL FOR PUBLIC REPOSITORIES</span></label><input class="form-input" id="modalToken" type="password" placeholder="Only needed for private repositories" autocomplete="off"><div class="callout">Public repositories can be connected without a token. For private repositories, enter a fine-grained GitHub token with Contents: Read and Metadata: Read. Webhooks: Read and write allows automatic push notifications; without it, Orbit polls for changes every three minutes. Any token you provide is encrypted in PostgreSQL.</div>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" data-connect>Connect and index →</button>`);$('#modalRoot [data-close]').onclick=closeModal;$('#modalRoot [data-connect]').onclick=async()=>{const name=$('#modalProject').value.trim(),repository=$('#modalRepo').value.trim(),githubToken=$('#modalToken').value;if(!name||!repository)return toast('Enter a project name and GitHub repository URL.');const btn=$('#modalRoot [data-connect]');btn.disabled=true;btn.textContent='Connecting…';try{const r=await orbitApi('/projects',{method:'POST',body:JSON.stringify({name,repository,githubToken})});closeModal();await orbitLoadProjects(r.project.id);toast('Repository connected. Initial indexing is running.')}catch(e){btn.disabled=false;btn.textContent='Connect and index →';toast(e.message)}}}
async function orbitAction(name){if(name==='repo')return orbitShowRepo();if(name==='assistantProvider')return orbitShowAiSettings();if(name==='sync'){try{await orbitApi(`/projects/${orbitProject.id}/sync`,{method:'POST',body:'{}'});toast('Repository sync started');setTimeout(()=>orbitLoadProject(),3000)}catch(e){toast(e.message)}}if(name==='exportDocs'){const blob=new Blob([orbitMarkdownExport()],{type:'text/markdown'});download(blob,`${orbitProject.repo_name}-documentation.md`)}if(name==='fitGraph')toast('Showing indexed project relationships');if(name==='deleteProject'){showModal('Remove project?',`<p class="subtitle">This permanently removes the project, source snapshots, generated documentation, versions, and encrypted token from this Orbit database.</p>`,`<button class="btn" data-close>Cancel</button><button class="btn" id="confirmRemove" style="color:var(--red)">Remove project</button>`);$('#modalRoot [data-close]').onclick=closeModal;$('#confirmRemove').onclick=async()=>{try{await orbitApi(`/projects/${orbitProject.id}`,{method:'DELETE'});closeModal();orbitProject=null;orbitKnowledge=null;await orbitLoadProjects()}catch(e){toast(e.message)}}}}
const orbitBaseAction=orbitAction;orbitAction=async function(name){if(name==='webhookInfo'){try{const w=await orbitApi(`/projects/${orbitProject.id}/webhook`);showModal('GitHub webhook setup',`<p class="subtitle">${w.publicHttps?'Public HTTPS endpoint':'This local endpoint is not reachable from GitHub. Periodic polling is active; use a public HTTPS URL only if you want webhooks.'}</p><label class="form-label">PAYLOAD URL</label><input class="form-input" readonly value="${orbitEsc(w.url)}"><label class="form-label">SECRET</label><input class="form-input" readonly value="${orbitEsc(w.secret)}"><div class="callout">In GitHub repository Settings → Webhooks, create a push-only webhook using this payload URL and secret. Orbit validates the HMAC signature and deduplicates delivery IDs. The webhook secret is encrypted at rest.</div>`,`<button class="btn" data-close>Close</button>`);$('#modalRoot [data-close]').onclick=closeModal}catch(e){toast(e.message)}return}return orbitBaseAction(name)};
const orbitBaseSettings=orbitSettings;orbitSettings=function(){return orbitBaseSettings().replace('<p class="skeleton-note">A signed GitHub push webhook was installed when repository permissions allowed it. Otherwise configure the endpoint shown when connecting.</p>','<button class="btn small" data-live-action="webhookInfo">View webhook setup</button><p class="skeleton-note" style="margin-top:8px">A signed GitHub push webhook may be installed when repository permissions and a public HTTPS URL are available. Default-branch polling runs every three minutes as a fallback.</p>')};
const orbitBaseAssistant=assistant;assistant=function(){const html=orbitBaseAssistant();const messages=orbitChat.length?orbitChat.map(m=>`<div class="chat-message ${m.role==='user'?'user':''}">${m.role==='user'?`<div class="chat-bubble">${orbitEsc(m.content)}</div><span class="chat-avatar you">ME</span>`:`<span class="chat-avatar">✳</span><div class="chat-bubble">${orbitMd(m.content)}<br><span class="skeleton-note">Sources: ${(m.citations||[]).map(x=>`<code>${orbitEsc(x)}</code>`).join(' · ')}</span></div>`}</div>`).join(''):'<div class="chat-message"><span class="chat-avatar">✳</span><div class="chat-bubble">Ask about a feature, file path, architecture relationship, or recent change. I search the indexed repository and cite the source files used in the answer.</div></div>';return html.replace(/<div class="chat-log" id="chatLog">[\s\S]*?<div class="chat-suggestions">/,`<div class="chat-log" id="chatLog">${messages}</div><div class="chat-suggestions">`)};
async function orbitAsk(question){question=question.trim();if(!question)return;const log=$('#chatLog');log.insertAdjacentHTML('beforeend',`<div class="chat-message user"><div class="chat-bubble">${orbitEsc(question)}</div><span class="chat-avatar you">ME</span></div><div class="chat-message" id="orbitThinking"><span class="chat-avatar">✳</span><div class="chat-bubble">Searching indexed source files…</div></div>`);$('#chatInput').value='';log.scrollTop=log.scrollHeight;try{const r=await orbitApi(`/projects/${orbitProject.id}/chat`,{method:'POST',body:JSON.stringify({question})});$('#orbitThinking .chat-bubble').innerHTML=`${orbitMd(r.answer)}<br><br><span class="skeleton-note">Sources: ${r.citations.map(x=>`<code>${orbitEsc(x)}</code>`).join(' · ')} · ${orbitEsc(r.model)}</span>`}catch(e){$('#orbitThinking .chat-bubble').textContent=e.message}log.scrollTop=log.scrollHeight}
function assistant(){return `${pageHeader('YOUR REPOSITORY, IN CONTEXT','Ask your project anything.','Answers from indexed repository code cite source files. Configure an AI model for synthesized, cross-file reasoning.',`<button class="btn small" data-live-action="assistantProvider">${orbitStatus?.assistant?'AI model configured':'Configure AI model'}</button>`)}<div class="chat-shell"><section class="card chat-main"><div class="chat-header"><div class="row"><div><h2>${orbitEsc(orbitProject.name)} assistant</h2><div class="skeleton-note">Repository ${orbitEsc(orbitProject.repo_owner)}/${orbitEsc(orbitProject.repo_name)} · commit ${orbitProject.last_commit_sha?.slice(0,7)||'pending'}</div></div></div></div><div class="chat-log" id="chatLog"><div class="chat-message"><span class="chat-avatar">✳</span><div class="chat-bubble">Ask about a feature, file path, architecture relationship, or recent change. I search the indexed repository and cite the source files used in the answer.</div></div></div><div class="chat-suggestions"><button data-prompt="Explain this project from its README and main entry points">Explain the project</button><button data-prompt="Which files are the main entry points?">Find entry points</button><button data-prompt="Explain the system architecture based on the source files">Architecture</button><button data-prompt="What changed in the latest commit?">Latest commit</button></div><form class="chat-input-row" id="chatForm"><input id="chatInput" placeholder="Ask about this repository…" autocomplete="off"><button class="btn primary small">Ask ↗</button></form><div class="skeleton-note" style="padding:9px 2px 0">Questions and answers are stored with this project. Source references are shown with each answer.</div></section><aside class="card chat-context">${cardTitle('ANSWER CONTEXT')}<div class="context-item"><span class="context-chip">CODE</span><span>${orbitFiles.length} indexed files</span></div><div class="context-item"><span class="context-chip">DOCS</span><span>${docs.length} guides</span></div><div class="context-item"><span class="context-chip">HISTORY</span><span>${commits.length} tracked commits</span></div><h3 style="margin-top:18px">Indexed source files</h3><div class="file-list">${orbitFiles.slice(0,8).map(f=>`<div class="file-row">↳ ${orbitEsc(f.path)}</div>`).join('')}</div><div class="callout">Answers are grounded in repository files and documentation. Configure a hosted model or local Ollama provider for synthesized multi-file explanations.</div></aside></div>`}
orbitAsk=async function(question){question=question.trim();if(!question)return;const log=$('#chatLog');log.insertAdjacentHTML('beforeend',`<div class="chat-message user"><div class="chat-bubble">${orbitEsc(question)}</div><span class="chat-avatar you">ME</span></div><div class="chat-message" id="orbitThinking"><span class="chat-avatar">✳</span><div class="chat-bubble">Searching indexed source files…</div></div>`);$('#chatInput').value='';log.scrollTop=log.scrollHeight;try{const r=await orbitApi(`/projects/${orbitProject.id}/chat`,{method:'POST',body:JSON.stringify({question})});orbitChat.push({role:'user',content:question,citations:[]},{role:'assistant',content:r.answer,citations:r.citations});$('#orbitThinking .chat-bubble').innerHTML=`${orbitMd(r.answer)}<br><br><span class="skeleton-note">Sources: ${r.citations.map(x=>`<code>${orbitEsc(x)}</code>`).join(' · ')} · ${orbitEsc(r.model)}</span>`}catch(e){$('#orbitThinking .chat-bubble').textContent=e.message}log.scrollTop=log.scrollHeight};
async function orbitInit(){try{orbitStatus=await orbitApi('/health');const r=await orbitApi('/auth/me');orbitUser=r.user;if(!orbitUser){orbitAuth();return}orbitAssistantSettings=await orbitApi("/assistant/settings");orbitStatus={...orbitStatus,assistant:orbitAssistantSettings.configured};await orbitLoadProjects()}catch(e){document.body.classList.add('signed-out');content.innerHTML=`<div class="auth-wrap"><div class="auth-card card"><div class="brand-mark">◈ orbit.</div><h1>Backend is not ready</h1><p class="subtitle">${orbitEsc(e.message)} Start the Orbit server and configure PostgreSQL using the setup guide in README.md.</p><div class="callout">The app now requires its real backend. No demo projects or simulated repository data are shown.</div></div></div>`}}
$('#newProject').onclick=()=>orbitShowRepo();$('#projectSelect').onclick=()=>{if(!state.projects.length)return orbitShowRepo();showModal('Your projects',`<p class="subtitle">Projects in your account</p><div class="file-list">${state.projects.map((p,i)=>`<div class="file-row project-picker" data-pick-live="${i}"><span style="color:var(--green)">◈</span><b>${orbitEsc(p.name)}</b><span>${orbitEsc(p.repo_owner)}/${orbitEsc(p.repo_name)}</span></div>`).join('')}</div>`,`<button class="btn" data-close>Close</button><button class="btn primary" data-add-live>＋ &nbsp; New project</button>`);$('#modalRoot [data-close]').onclick=closeModal;$('#modalRoot [data-add-live]').onclick=()=>{closeModal();orbitShowRepo()};$$('[data-pick-live]').forEach(el=>el.onclick=async()=>{closeModal();orbitProject=state.projects[+el.dataset.pickLive];orbitDiff=null;state.page='overview';await orbitLoadProject()})};$('#themeToggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('orbit-theme',state.theme);render()};$('#accountButton').onclick=async()=>{try{await orbitApi('/auth/logout',{method:'POST',body:'{}'});orbitUser=null;orbitProject=null;state.projects=[];orbitAuth()}catch(e){toast(e.message)}};$$('.nav-item').forEach(el=>el.onclick=()=>navigate(el.dataset.page));
$('#globalSearch').addEventListener('input',()=>setTimeout(()=>{const q=$('#globalSearch').value.trim().toLowerCase(),box=$('#searchResults');if(!q||!orbitUser||!box)return;const files=orbitFiles.filter(f=>`${f.path} ${f.language} ${(f.imports||[]).join(' ')}`.toLowerCase().includes(q)).slice(0,5);if(!files.length)return;box.classList.add('show');box.insertAdjacentHTML('afterbegin',files.map(f=>`<div class="search-result source-search" data-file-path="${orbitEsc(f.path)}">⌕ &nbsp; Source · ${orbitEsc(f.path)}</div>`).join(''));box.querySelectorAll('.source-search').forEach(el=>el.onclick=async()=>{try{const f=await orbitApi(`/projects/${orbitProject.id}/file?path=${encodeURIComponent(el.dataset.filePath)}`);showModal(f.path,`<div class="doc-meta">${orbitEsc(f.language)} · ${f.content.length.toLocaleString()} characters</div><pre class="source-preview">${orbitEsc(f.content.slice(0,12000))}${f.content.length>12000?'\n… truncated':''}</pre>`,`<button class="btn" data-close>Close</button>`);$('#modalRoot [data-close]').onclick=closeModal;$('#searchResults')?.classList.remove('show');$('#globalSearch').value=''}catch(e){toast(e.message)}})},0));
orbitInit();
setInterval(async()=>{if(!orbitUser||!orbitProject||orbitLoading)return;try{const r=await orbitApi(`/projects/${orbitProject.id}`);const p=r.project;if(p.last_commit_sha!==orbitProject.last_commit_sha||p.index_status!==orbitProject.index_status){orbitProject={...orbitProject,...p};await orbitLoadProject()}else orbitProject.last_indexed_at=p.last_indexed_at}catch(e){console.warn('Orbit status refresh:',e.message)}},30000);
const orbitProjectAssistant=assistant;assistant=function(){const html=orbitProjectAssistant(),ready=!!orbitStatus?.assistant;return html.replace('Answers retrieved from this project’s indexed code with source-file citations.',ready?'Answers synthesized from this project’s indexed source and citations.':'Repository evidence assistant · answers combine indexed code, generated documentation, architecture and commit history.').replace('Answers use source excerpts from this repository. Configure OPENAI_API_KEY on the server for synthesized multi-file explanations.',ready?'The language model receives repository evidence and cites the source paths.':'For natural-language synthesis, configure an OpenAI-compatible provider or local Ollama endpoint. Evidence-based answers remain available without a model key.').replace(/<span class="tag green">\d+ SOURCE FILES<\/span>/,`<span class="tag ${ready?'green':'yellow'}">${ready?'LANGUAGE MODEL':'EVIDENCE MODE'} · ${orbitFiles.length} FILES</span>`)};
const orbitProjectOverview=orbitOverview;orbitOverview=function(){let html=orbitProjectOverview();if(orbitProject.index_status==='indexing')html=html.replace('<div class="stats">','<div class="callout"><span class="sync-pulse"></span> Repository indexing is in progress. Commit, file and documentation totals update when the snapshot is ready.</div><div class="stats">');if(orbitProject.index_status==='error')html=html.replace('<div class="stats">',`<div class="callout">Repository sync failed: ${orbitEsc(orbitProject.index_error||'Unknown indexing error.')} <button class="btn small" data-live-action="sync">Retry sync</button></div><div class="stats">`);return html};
const orbitProjectChangeView=orbitRenderChanges;orbitRenderChanges=async function(){let html=await orbitProjectChangeView(),c=commits[state.activeCommit||0],x=c?.impact||{},b=x.before_after;const areas=x.functional_areas?.length?`<div class="card" style="margin:0 0 14px;padding:14px 18px"><div class="eyebrow">FUNCTIONALITY AREAS TO REVIEW</div><p>${x.functional_areas.map(orbitEsc).join(' · ')}</p>${x.risk_factors?.length?`<div class="risk-box"><b>Why this risk was assigned</b><br>${x.risk_factors.map(orbitEsc).join('<br>')}</div>`:''}${b?`<div class="impact-summary"><div class="impact-pill"><small>PREVIOUS FILES</small><b>${b.previous_file_count}</b></div><div class="impact-pill"><small>CURRENT FILES</small><b>${b.current_file_count}</b></div><div class="impact-pill"><small>ADDED / MODIFIED / REMOVED</small><b>${b.added} / ${b.modified} / ${b.removed}</b></div><div class="impact-pill"><small>RISK SCORE</small><b>${x.risk_score??'—'} / 100</b></div></div>`:''}</div>`:'';return html.replace('<div class="change-grid">',`${areas}<div class="change-grid">`)};
const orbitSettingsWithProvider=orbitSettings;orbitSettings=function(){return orbitSettingsWithProvider().replace('</section><section class="card settings-card"><button class="btn" data-live-action="deleteProject">',`<div class="settings-row"><div><b>AI assistant provider</b><small>${orbitAssistantSettings?.configured?'Configured':'Repository evidence mode'}</small></div><button class="btn small" data-live-action="aiSettings">Configure provider</button></div></section><section class="card settings-card"><button class="btn" data-live-action="deleteProject">`)};
async function orbitShowAiSettings(){try{const s=await orbitApi('/assistant/settings');orbitAssistantSettings=s;showModal('Configure project assistant',`<p class="subtitle">Connect an OpenAI-compatible API, including a local Ollama server. API keys are encrypted in your PostgreSQL database and never returned to the browser.</p><label class="form-label">API BASE URL</label><input class="form-input" id="aiBaseUrl" value="${orbitEsc(s.baseUrl||'')}" placeholder="Blank for OpenAI · http://localhost:11434/v1 for Ollama"><label class="form-label">MODEL NAME</label><input class="form-input" id="aiModel" value="${orbitEsc(s.model||'')}" placeholder="gpt-4o-mini or llama3.2"><label class="form-label">API KEY</label><input class="form-input" id="aiApiKey" type="password" autocomplete="new-password" placeholder="${s.hasKey?'Saved securely · leave blank to keep it':'Required for hosted providers · Ollama uses no key'}"><label class="row" style="margin-top:12px;gap:8px"><input id="aiClearKey" type="checkbox"> Clear my saved API key</label><div class="callout" style="margin-top:12px">For Ollama, install and run Ollama on this laptop, then pull a model (for example, <code>ollama pull llama3.2</code>). Use the local URL above and that model name. For a hosted service, use its OpenAI-compatible base URL and API key.</div>`,`<button class="btn" data-close>Cancel</button><button class="btn" data-ai-clear>Clear provider</button><button class="btn primary" data-ai-save>Save provider</button>`);$('#modalRoot [data-close]').onclick=closeModal;$('#modalRoot [data-ai-save]').onclick=async()=>{const key=$('#aiApiKey').value;try{orbitAssistantSettings=await orbitApi('/assistant/settings',{method:'PUT',body:JSON.stringify({baseUrl:$('#aiBaseUrl').value,model:$('#aiModel').value,apiKey:key||undefined,clearApiKey:$('#aiClearKey').checked})});orbitStatus={...orbitStatus,assistant:orbitAssistantSettings.configured};closeModal();render();toast('Assistant provider settings saved.')}catch(e){toast(e.message)}};$('#modalRoot [data-ai-clear]').onclick=async()=>{try{orbitAssistantSettings=await orbitApi('/assistant/settings',{method:'PUT',body:JSON.stringify({baseUrl:'',model:'',clearApiKey:true})});orbitStatus={...orbitStatus,assistant:orbitAssistantSettings.configured};closeModal();render();toast('Custom assistant provider cleared.')}catch(e){toast(e.message)}}}catch(e){toast(e.message)}}
const orbitActionWithProvider=orbitAction;orbitAction=async function(name){if(name==='aiSettings')return orbitShowAiSettings();return orbitActionWithProvider(name)};
